#!/usr/bin/env bash
# The README's quickstart, as the recorded walkthrough shows it: clone, start
# the stack, sign in by magic link, get an Oxy API key, get "pong" through the
# gateway. Every command is printed, then run exactly as printed.
#
# .github/workflows/walkthrough.yml records it with asciinema on a clean runner:
#   asciinema rec --command "bash scripts/walkthrough.sh" walkthrough.cast
#
# The session token and the API key are generated by the run and shown only by
# their first characters.
set -euo pipefail

REPO_URL="${REPO_URL:-https://github.com/heyvaldemar/oxy-llm-gateway.git}"
EMAIL="you@example.com"
RUNNER_TEMP_DIR="${RUNNER_TEMP:-/tmp}"

typed() {
  printf '\033[1;32m$\033[0m '
  local text=$1 i
  for ((i = 0; i < ${#text}; i++)); do printf '%s' "${text:i:1}"; sleep 0.012; done
  printf '\n'
}
run() { typed "$1"; eval "$1"; }
note() { printf '\n\033[2m# %s\033[0m\n' "$1"; sleep 0.8; }

note "Oxy from a clean clone. Docker is the only requirement."
run "git clone --quiet $REPO_URL && cd oxy-llm-gateway"

note "The whole stack, no .env file and no provider key. The build takes a few minutes."
typed "docker compose up -d --build --wait"
if ! docker compose up -d --build --wait >"$RUNNER_TEMP_DIR/compose-up.log" 2>&1; then
  tail -40 "$RUNNER_TEMP_DIR/compose-up.log"; exit 1
fi
printf '\033[2m(%s lines of build output hidden)\033[0m\n' "$(wc -l <"$RUNNER_TEMP_DIR/compose-up.log" | tr -d ' ')"
run "docker compose ps --format 'table {{.Service}}\t{{.Status}}'"

note "Sign in by magic link: GoTrue sends it, Mailpit catches it."
run "ANON_KEY=\$(docker compose config --format json | jq -r .services.ui.environment.NEXT_PUBLIC_SUPABASE_ANON_KEY)"
run "curl -s -X POST localhost:8080/auth/v1/otp -H \"apikey: \$ANON_KEY\" -H 'Content-Type: application/json' -d '{\"email\":\"$EMAIL\"}'; echo"
sleep 2
run "LINK=\$(curl -s localhost:8025/api/v1/message/latest | jq -r .Text | grep -o 'http://[^ ]*/auth/v1/verify[^ ]*')"
note "The link and the tokens reach curl on its standard input (--config -), never on its command line, where ps shows them."
run "TOKEN=\$(printf 'url = \"%s\"\\n' \"\$LINK\" | curl -s --config - -o /dev/null -w '%{redirect_url}' | grep -o 'access_token=[^&]*' | cut -d= -f2)"
run "echo \"signed in, session \${TOKEN:0:12}...\""

note "Onboarding makes an organization, a project and an Oxy API key."
run "as_user() { printf 'header = \"Authorization: Bearer %s\"\\n' \"\$TOKEN\" | curl --config - \"\$@\"; }"
run "OXY_API_KEY=\$(as_user -s -X POST localhost:8000/management/onboard -H 'X-CSRF-Token: demo' -b csrf_token=demo -H 'Content-Type: application/json' -d '{\"full_name\":\"You\",\"email\":\"$EMAIL\"}' | jq -r .api_key)"
run "echo \"Oxy API key \${OXY_API_KEY:0:13}...\""

note "A request through the gateway, to its built-in healthcheck model (no provider key needed)."
run "oxy() { printf 'header = \"Authorization: Bearer %s\"\\n' \"\$OXY_API_KEY\" | curl --config - \"\$@\"; }"
run "oxy -s localhost:8000/v1/chat/completions -H 'Content-Type: application/json' -d '{\"model\":\"gpt-4.1-mini\",\"messages\":[{\"role\":\"system\",\"content\":\"You are a healthcheck bot for the Oxy Gateway.\"},{\"role\":\"user\",\"content\":\"ping\"}]}' | jq -r '.choices[0].message.content'"
sleep 3
